package com.loopers.interfaces.api.payment;import com.loopers.application.payment.PaymentFacade;import com.loopers.domain.payment.PaymentIntent;import com.loopers.interfaces.api.ApiResponse;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/payments") public class PaymentCallbackController{private final PaymentFacade facade;@PostMapping("/callback")public ApiResponse<PaymentIntent.Status> callback(@RequestBody Callback r){return ApiResponse.success(facade.callback(r.orderId(),r.transactionKey(),r.status()).getStatus());}public record Callback(String transactionKey,String orderId,String status){}}
